fn set_int(xs: List[Int], idx: Int, v: Int) -> List[Int] {
    var out: List[Int] = []
    var i = 0
    for x in xs {
        if i == idx {
            out = out.push(v)
        } else {
            out = out.push(x)
        }
        i = i + 1
    }
    return out
}

fn chars_list(s: Str) -> List[Str] {
    var out: List[Str] = []
    for c in s.chars() {
        out = out.push(c)
    }
    return out
}

fn one_diff(a: Str, b: Str) -> Bool {
    let ca = chars_list(s: a)
    let cb = chars_list(s: b)
    if ca.len() != cb.len() {
        return false
    }
    var diff = 0
    var i = 0
    while i < ca.len() {
        if str_at(ca, i) != str_at(cb, i) {
            diff = diff + 1
        }
        i = i + 1
    }
    return diff == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
    if start == goal {
        return 1
    }
    var nodes: List[Str] = [start]
    var has_goal = false
    for w in words {
        nodes = nodes.push(w)
        if w == goal {
            has_goal = true
        }
    }
    if not has_goal {
        return 0
    }

    let n = nodes.len()
    var dist: List[Int] = []
    var k = 0
    while k < n {
        dist = dist.push(-1)
        k = k + 1
    }
    dist = set_int(xs: dist, idx: 0, v: 1)

    var queue: List[Int] = [0]
    var head = 0
    while head < queue.len() {
        let u = at(queue, head)
        head = head + 1
        var v = 0
        while v < n {
            if at(dist, v) == -1 and one_diff(a: str_at(nodes, u), b: str_at(nodes, v)) {
                let dv = at(dist, u) + 1
                dist = set_int(xs: dist, idx: v, v: dv)
                if str_at(nodes, v) == goal {
                    return dv
                }
                queue = queue.push(v)
            }
            v = v + 1
        }
    }
    return 0
}
